/* =================================================================
 *  Minimal freestanding C library for the doomgeneric MIPS target.
 *  All OS interaction goes through the custom syscall ABI expected
 *  by vm.js:  v0 = syscall number, a0/a1/a2 = args, result in v0.
 *  Syscall numbers (x86-64-like): read=0 write=1 open=2 close=3
 *  lseek=8 time=201 rename=38 mkdir=39.
 * ================================================================= */

int errno = 0;

/* ---------------- raw syscalls ---------------- */
static inline long __sc3(long n, long a, long b, long c)
{
    register long v0 asm("$2") = n;
    register long a0 asm("$4") = a;
    register long a1 asm("$5") = b;
    register long a2 asm("$6") = c;
    asm volatile("syscall"
                 : "+r"(v0)
                 : "r"(a0), "r"(a1), "r"(a2)
                 : "memory");
    return v0;
}

long read(int fd, void *buf, unsigned long n)  { return __sc3(0, fd, (long)buf, n); }
long write(int fd, const void *buf, unsigned long n) { return __sc3(1, fd, (long)buf, n); }
int  close(int fd) { return (int)__sc3(3, fd, 0, 0); }
long lseek(int fd, long off, int whence) { return __sc3(8, fd, off, whence); }
time_t time(time_t *t) { long r = __sc3(201, (long)t, 0, 0); if (t) *t = r; return r; }

int open(const char *path, int flags, ...)
{
    return (int)__sc3(2, (long)path, flags, 0666);
}

int mkdir(const char *path, unsigned int mode) { return (int)__sc3(39, (long)path, mode, 0); }
int rename(const char *a, const char *b) { return (int)__sc3(38, (long)a, (long)b, 0); }
int unlink(const char *p) { (void)p; return 0; }
int remove(const char *p) { (void)p; return 0; }
int access(const char *p, int m) { (void)p; (void)m; return -1; }

/* ---------------- string / memory ---------------- */
void *memset(void *d, int c, size_t n)
{
    unsigned char *p = (unsigned char *)d;
    while (n--) *p++ = (unsigned char)c;
    return d;
}
void *memcpy(void *d, const void *s, size_t n)
{
    unsigned char *dp = (unsigned char *)d;
    const unsigned char *sp = (const unsigned char *)s;
    while (n--) *dp++ = *sp++;
    return d;
}
void *memmove(void *d, const void *s, size_t n)
{
    unsigned char *dp = (unsigned char *)d;
    const unsigned char *sp = (const unsigned char *)s;
    if (dp < sp) { while (n--) *dp++ = *sp++; }
    else { dp += n; sp += n; while (n--) *--dp = *--sp; }
    return d;
}
int memcmp(const void *a, const void *b, size_t n)
{
    const unsigned char *pa = a, *pb = b;
    while (n--) { if (*pa != *pb) return *pa - *pb; pa++; pb++; }
    return 0;
}
void *memchr(const void *s, int c, size_t n)
{
    const unsigned char *p = s;
    while (n--) { if (*p == (unsigned char)c) return (void *)p; p++; }
    return NULL;
}
size_t strlen(const char *s) { const char *p = s; while (*p) p++; return p - s; }
char *strcpy(char *d, const char *s) { char *r = d; while ((*d++ = *s++)); return r; }
char *strncpy(char *d, const char *s, size_t n)
{
    char *r = d;
    while (n && (*d = *s)) { d++; s++; n--; }
    while (n--) *d++ = 0;
    return r;
}
char *strcat(char *d, const char *s) { char *r = d; while (*d) d++; while ((*d++ = *s++)); return r; }
char *strncat(char *d, const char *s, size_t n)
{
    char *r = d; while (*d) d++;
    while (n && *s) { *d++ = *s++; n--; }
    *d = 0; return r;
}
int strcmp(const char *a, const char *b)
{
    while (*a && *a == *b) { a++; b++; }
    return (unsigned char)*a - (unsigned char)*b;
}
int strncmp(const char *a, const char *b, size_t n)
{
    while (n && *a && *a == *b) { a++; b++; n--; }
    if (!n) return 0;
    return (unsigned char)*a - (unsigned char)*b;
}
static int lc(int c) { return (c >= 'A' && c <= 'Z') ? c + 32 : c; }
int strcasecmp(const char *a, const char *b)
{
    while (*a && lc(*a) == lc(*b)) { a++; b++; }
    return lc((unsigned char)*a) - lc((unsigned char)*b);
}
int strncasecmp(const char *a, const char *b, size_t n)
{
    while (n && *a && lc(*a) == lc(*b)) { a++; b++; n--; }
    if (!n) return 0;
    return lc((unsigned char)*a) - lc((unsigned char)*b);
}
char *strchr(const char *s, int c)
{
    while (*s) { if (*s == (char)c) return (char *)s; s++; }
    return (c == 0) ? (char *)s : NULL;
}
char *strrchr(const char *s, int c)
{
    const char *last = NULL;
    do { if (*s == (char)c) last = s; } while (*s++);
    return (char *)last;
}
char *strstr(const char *h, const char *n)
{
    if (!*n) return (char *)h;
    for (; *h; h++) {
        const char *a = h, *b = n;
        while (*a && *b && *a == *b) { a++; b++; }
        if (!*b) return (char *)h;
    }
    return NULL;
}
size_t strspn(const char *s, const char *set)
{
    const char *p = s;
    for (; *p; p++) { const char *q = set; while (*q && *q != *p) q++; if (!*q) break; }
    return p - s;
}
size_t strcspn(const char *s, const char *set)
{
    const char *p = s;
    for (; *p; p++) { const char *q = set; while (*q && *q != *p) q++; if (*q) break; }
    return p - s;
}
char *strpbrk(const char *s, const char *set)
{
    for (; *s; s++) { const char *q = set; while (*q) { if (*q == *s) return (char *)s; q++; } }
    return NULL;
}
char *strtok(char *s, const char *delim)
{
    static char *save;
    if (s) save = s;
    if (!save) return NULL;
    while (*save && strchr(delim, *save)) save++;
    if (!*save) { save = NULL; return NULL; }
    char *start = save;
    while (*save && !strchr(delim, *save)) save++;
    if (*save) { *save++ = 0; } else { save = NULL; }
    return start;
}
char *strerror(int e) { (void)e; return "error"; }
void *__memcpy(void *d, const void *s, size_t n) { return memcpy(d, s, n); }

/* ---------------- ctype ---------------- */
int isspace(int c) { return c == ' ' || (c >= 9 && c <= 13); }
int isdigit(int c) { return c >= '0' && c <= '9'; }
int isxdigit(int c) { return isdigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'); }
int isupper(int c) { return c >= 'A' && c <= 'Z'; }
int islower(int c) { return c >= 'a' && c <= 'z'; }
int isalpha(int c) { return isupper(c) || islower(c); }
int isalnum(int c) { return isalpha(c) || isdigit(c); }
int iscntrl(int c) { return (c >= 0 && c < 32) || c == 127; }
int isprint(int c) { return c >= 32 && c < 127; }
int isgraph(int c) { return c > 32 && c < 127; }
int ispunct(int c) { return isprint(c) && c != ' ' && !isalnum(c); }
int toupper(int c) { return islower(c) ? c - 32 : c; }
int tolower(int c) { return isupper(c) ? c + 32 : c; }

