long strtol(const char *s, char **end, int base)
{
    const char *p = s;
    while (isspace((unsigned char)*p)) p++;
    int neg = 0;
    if (*p == '+' || *p == '-') { neg = (*p == '-'); p++; }
    if ((base == 0 || base == 16) && p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) { p += 2; base = 16; }
    else if (base == 0 && p[0] == '0') { base = 8; }
    else if (base == 0) { base = 10; }
    long val = 0;
    for (;;) {
        int c = (unsigned char)*p, d;
        if (isdigit(c)) d = c - '0';
        else if (c >= 'a' && c <= 'z') d = c - 'a' + 10;
        else if (c >= 'A' && c <= 'Z') d = c - 'A' + 10;
        else break;
        if (d >= base) break;
        val = val * base + d;
        p++;
    }
    if (end) *end = (char *)p;
    return neg ? -val : val;
}
unsigned long strtoul(const char *s, char **end, int base) { return (unsigned long)strtol(s, end, base); }
int atoi(const char *s) { return (int)strtol(s, NULL, 10); }
long atol(const char *s) { return strtol(s, NULL, 10); }

double strtod(const char *s, char **end)
{
    const char *p = s;
    while (isspace((unsigned char)*p)) p++;
    int neg = 0;
    if (*p == '+' || *p == '-') { neg = (*p == '-'); p++; }
    double val = 0.0;
    while (isdigit((unsigned char)*p)) { val = val * 10.0 + (*p - '0'); p++; }
    if (*p == '.') {
        p++;
        double f = 0.1;
        while (isdigit((unsigned char)*p)) { val += (*p - '0') * f; f *= 0.1; p++; }
    }
    if (*p == 'e' || *p == 'E') {
        p++;
        int eneg = 0;
        if (*p == '+' || *p == '-') { eneg = (*p == '-'); p++; }
        int e = 0;
        while (isdigit((unsigned char)*p)) { e = e * 10 + (*p - '0'); p++; }
        double m = 1.0;
        while (e--) m *= 10.0;
        if (eneg) val /= m; else val *= m;
    }
    if (end) *end = (char *)p;
    return neg ? -val : val;
}
double atof(const char *s) { return strtod(s, NULL); }

