/* ---------------- qsort (insertion for simplicity) ---------------- */
static void __swap(char *a, char *b, size_t n) { while (n--) { char t = *a; *a++ = *b; *b++ = t; } }
void qsort(void *base, size_t nmemb, size_t size, int (*cmp)(const void *, const void *))
{
    char *arr = (char *)base;
    for (size_t i = 1; i < nmemb; i++) {
        for (size_t j = i; j > 0 && cmp(arr + (j - 1) * size, arr + j * size) > 0; j--)
            __swap(arr + (j - 1) * size, arr + j * size, size);
    }
}

/* ================================================================
 *  malloc / free  --  K&R style first-fit allocator over sbrk heap
 * ================================================================ */
extern char _heap_start[];
static char *__brk = 0;

static void *sbrk(long inc)
{
    if (__brk == 0) __brk = (char *)_heap_start;
    char *old = __brk;
    __brk += inc;
    return old;
}

typedef long Align;
typedef union header {
    struct { union header *next; size_t size; } s; /* size in units of header */
    Align x;
} Header;

static Header base;
static Header *freep = 0;

#define NALLOC 4096u

static Header *morecore(size_t nu)
{
    if (nu < NALLOC) nu = NALLOC;
    char *cp = (char *)sbrk((long)(nu * sizeof(Header)));
    if (cp == (char *)-1) return 0;
    Header *up = (Header *)cp;
    up->s.size = nu;
    free((void *)(up + 1));
    return freep;
}

void *malloc(size_t nbytes)
{
    Header *p, *prevp;
    size_t nunits = (nbytes + sizeof(Header) - 1) / sizeof(Header) + 1;
    if ((prevp = freep) == 0) {
        base.s.next = freep = prevp = &base;
        base.s.size = 0;
    }
    for (p = prevp->s.next;; prevp = p, p = p->s.next) {
        if (p->s.size >= nunits) {
            if (p->s.size == nunits) {
                prevp->s.next = p->s.next;
            } else {
                p->s.size -= nunits;
                p += p->s.size;
                p->s.size = nunits;
            }
            freep = prevp;
            return (void *)(p + 1);
        }
        if (p == freep) {
            if ((p = morecore(nunits)) == 0) return 0;
        }
    }
}

void free(void *ap)
{
    if (!ap) return;
    Header *bp = (Header *)ap - 1;
    Header *p;
    for (p = freep; !(bp > p && bp < p->s.next); p = p->s.next)
        if (p >= p->s.next && (bp > p || bp < p->s.next)) break;
    if (bp + bp->s.size == p->s.next) {
        bp->s.size += p->s.next->s.size;
        bp->s.next = p->s.next->s.next;
    } else {
        bp->s.next = p->s.next;
    }
    if (p + p->s.size == bp) {
        p->s.size += bp->s.size;
        p->s.next = bp->s.next;
    } else {
        p->s.next = bp;
    }
    freep = p;
}

void *calloc(size_t n, size_t sz)
{
    size_t total = n * sz;
    void *p = malloc(total);
    if (p) memset(p, 0, total);
    return p;
}

void *realloc(void *ptr, size_t nbytes)
{
    if (!ptr) return malloc(nbytes);
    if (nbytes == 0) { free(ptr); return NULL; }
    Header *bp = (Header *)ptr - 1;
    size_t oldbytes = (bp->s.size - 1) * sizeof(Header);
    if (oldbytes >= nbytes) return ptr;
    void *np = malloc(nbytes);
    if (!np) return NULL;
    memcpy(np, ptr, oldbytes);
    free(ptr);
    return np;
}

char *strdup(const char *s)
{
    size_t n = strlen(s) + 1;
    char *p = malloc(n);
    if (p) memcpy(p, s, n);
    return p;
}

/* ================================================================
 *  Formatted output core
 * ================================================================ */
typedef struct { char *buf; size_t cap; size_t len; int fd; } OutCtx;

static void out_ch(OutCtx *o, char c)
{
    if (o->fd >= 0) {
        write(o->fd, &c, 1);
    } else {
        if (o->len + 1 < o->cap) o->buf[o->len] = c;
        o->len++;
    }
}
static void out_str(OutCtx *o, const char *s) { while (*s) out_ch(o, *s++); }

static int fmt_core(OutCtx *o, const char *fmt, va_list ap)
{
    char numbuf[32];
    for (; *fmt; fmt++) {
        if (*fmt != '%') { out_ch(o, *fmt); continue; }
        fmt++;
        int left = 0, zero = 0, plus = 0, space = 0, alt = 0;
        for (;; fmt++) {
            if (*fmt == '-') left = 1;
            else if (*fmt == '0') zero = 1;
            else if (*fmt == '+') plus = 1;
            else if (*fmt == ' ') space = 1;
            else if (*fmt == '#') alt = 1;
            else break;
        }
        int width = 0;
        if (*fmt == '*') { width = va_arg(ap, int); fmt++; if (width < 0) { left = 1; width = -width; } }
        else while (isdigit((unsigned char)*fmt)) { width = width * 10 + (*fmt - '0'); fmt++; }
        int prec = -1;
        if (*fmt == '.') {
            fmt++;
            prec = 0;
            if (*fmt == '*') { prec = va_arg(ap, int); fmt++; }
            else while (isdigit((unsigned char)*fmt)) { prec = prec * 10 + (*fmt - '0'); fmt++; }
        }
        int lng = 0;
        while (*fmt == 'l' || *fmt == 'h' || *fmt == 'z' || *fmt == 'j' || *fmt == 't') {
            if (*fmt == 'l') lng++;
            fmt++;
        }
        char conv = *fmt;
        char *s = numbuf;
        const char *out = numbuf;
        int isneg = 0;
        unsigned long uval = 0;
        int base = 10, upper = 0, isnum = 0;
        switch (conv) {
        case 'd': case 'i': {
            long v = lng ? va_arg(ap, long) : va_arg(ap, int);
            if (v < 0) { isneg = 1; uval = (unsigned long)(-v); } else uval = (unsigned long)v;
            isnum = 1; base = 10;
            break;
        }
        case 'u': uval = lng ? va_arg(ap, unsigned long) : va_arg(ap, unsigned int); isnum = 1; base = 10; break;
        case 'x': uval = lng ? va_arg(ap, unsigned long) : va_arg(ap, unsigned int); isnum = 1; base = 16; break;
        case 'X': uval = lng ? va_arg(ap, unsigned long) : va_arg(ap, unsigned int); isnum = 1; base = 16; upper = 1; break;
        case 'o': uval = lng ? va_arg(ap, unsigned long) : va_arg(ap, unsigned int); isnum = 1; base = 8; break;
        case 'p': uval = (unsigned long)va_arg(ap, void *); isnum = 1; base = 16; alt = 1; break;
        case 'c': { numbuf[0] = (char)va_arg(ap, int); numbuf[1] = 0; out = numbuf; break; }
        case 's': {
            out = va_arg(ap, const char *);
            if (!out) out = "(null)";
            break;
        }
        case '%': numbuf[0] = '%'; numbuf[1] = 0; out = numbuf; break;
        case 'f': case 'F': case 'g': case 'G': case 'e': case 'E': {
            double d = va_arg(ap, double);
            if (prec < 0) prec = 6;
            char *bp = numbuf;
            if (d < 0) { *bp++ = '-'; d = -d; }
            unsigned long ip = (unsigned long)d;
            double frac = d - (double)ip;
            char tmp[24]; int ti = 0;
            if (ip == 0) tmp[ti++] = '0';
            while (ip) { tmp[ti++] = '0' + (ip % 10); ip /= 10; }
            while (ti) *bp++ = tmp[--ti];
            if (prec > 0) {
                *bp++ = '.';
                for (int k = 0; k < prec && k < 12; k++) {
                    frac *= 10.0;
                    int dg = (int)frac;
                    if (dg > 9) dg = 9;
                    *bp++ = '0' + dg;
                    frac -= dg;
                }
            }
            *bp = 0;
            out = numbuf;
            /* skip generic numeric path */
            {
                int len = strlen(out);
                int pad = width - len;
                if (!left) { char pc = ' '; while (pad-- > 0) out_ch(o, pc); }
                out_str(o, out);
                if (left) { while (pad-- > 0) out_ch(o, ' '); }
            }
            continue;
        }
        default:
            out_ch(o, '%');
            if (conv) out_ch(o, conv);
            continue;
        }

        if (isnum) {
            char tmp[32]; int ti = 0;
            const char *digs = upper ? "0123456789ABCDEF" : "0123456789abcdef";
            if (uval == 0) tmp[ti++] = '0';
            while (uval) { tmp[ti++] = digs[uval % base]; uval /= base; }
            char *bp = numbuf;
            /* precision for ints = min digits */
            int zeros = 0;
            if (prec >= 0 && prec > ti) zeros = prec - ti;
            char sign = 0;
            if (isneg) sign = '-'; else if (plus) sign = '+'; else if (space) sign = ' ';
            char pfx0 = 0, pfx1 = 0;
