            int total = ti + zeros + (sign ? 1 : 0) + (pfx0 ? 2 : 0);
            int pad = width - total;
            if (!left && !zero) { while (pad-- > 0) out_ch(o, ' '); }
            if (sign) out_ch(o, sign);
            if (pfx0) { out_ch(o, pfx0); out_ch(o, pfx1); }
            if (!left && zero && prec < 0) { while (pad-- > 0) out_ch(o, '0'); }
            while (zeros-- > 0) out_ch(o, '0');
            while (ti) *bp++ = tmp[--ti];
