            out_str(o, numbuf);
            if (left) { while (pad-- > 0) out_ch(o, ' '); }
            continue;
        }

        /* string / char */
        {
            int len = 0;
            const char *q = out;
            while (q[len]) len++;
            if (prec >= 0 && prec < len) len = prec;
            int pad = width - len;
