/* ---------------- stdio file ops ---------------- */
FILE *fopen(const char *path, const char *mode)
{
    int flags = 0, wr = 0;
    if (mode[0] == 'r') { flags = 0; if (strchr(mode, '+')) { flags = 2; wr = 1; } }
    else if (mode[0] == 'w') { flags = 1 | 64 | 512; wr = 1; if (strchr(mode, '+')) flags = 2 | 64 | 512; }
    else if (mode[0] == 'a') { flags = 1 | 64 | 1024; wr = 1; if (strchr(mode, '+')) flags = 2 | 64 | 1024; }
    int fd = open(path, flags, 0666);
    if (fd < 0) return NULL;
    FILE *f = (FILE *)malloc(sizeof(FILE));
    if (!f) { close(fd); return NULL; }
    f->fd = fd; f->eof = 0; f->err = 0; f->wr = wr;
    return f;
}
