}
size_t fread(void *ptr, size_t sz, size_t nm, FILE *f)
{
    if (!f || sz == 0) return 0;
    unsigned long total = (unsigned long)sz * nm;
    unsigned long done = 0;
    char *p = (char *)ptr;
    while (done < total) {
        long r = read(f->fd, p + done, total - done);
        if (r <= 0) { if (r == 0) f->eof = 1; else f->err = 1; break; }
        done += r;
    }
    return done / sz;
}
size_t fwrite(const void *ptr, size_t sz, size_t nm, FILE *f)
{
