/* ---------------- sscanf (limited) ---------------- */
static const char *scan_int(const char *p, int base, long *out)
{
    while (isspace((unsigned char)*p)) p++;
    int neg = 0;
    if (*p == '+' || *p == '-') { neg = (*p == '-'); p++; }
    if ((base == 16) && p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) p += 2;
    if (base == 0) {
        if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) { base = 16; p += 2; }
        else if (p[0] == '0') base = 8;
        else base = 10;
    }
    long v = 0; int any = 0;
    for (;;) {
        int c = (unsigned char)*p, d;
        if (isdigit(c)) d = c - '0';
        else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
        else break;
        if (d >= base) break;
        v = v * base + d; p++; any = 1;
    }
    if (!any) return NULL;
    *out = neg ? -v : v;
    return p;
}

int vsscanf_impl(const char *str, const char *fmt, va_list ap)
{
    const char *s = str;
    int count = 0;
    for (; *fmt; fmt++) {
        if (isspace((unsigned char)*fmt)) { while (isspace((unsigned char)*s)) s++; continue; }
        if (*fmt != '%') {
            if (*s != *fmt) break;
            s++; continue;
        }
        fmt++;
        int suppress = 0;
        if (*fmt == '*') { suppress = 1; fmt++; }
        int width = 0;
        while (isdigit((unsigned char)*fmt)) { width = width * 10 + (*fmt - '0'); fmt++; }
        while (*fmt == 'l' || *fmt == 'h') fmt++;
        char conv = *fmt;
        long v; const char *np;
        int base = 10;
        switch (conv) {
        case 'd': base = 10; goto doint;
        case 'u': base = 10; goto doint;
        case 'i': base = 0; goto doint;
        case 'x': base = 16; goto doint;
        case 'o': base = 8; goto doint;
        doint:
            np = scan_int(s, base, &v);
            if (!np) return count;
            s = np;
            if (!suppress) { *va_arg(ap, int *) = (int)v; count++; }
            break;
        case 's': {
            while (isspace((unsigned char)*s)) s++;
            char *dst = suppress ? NULL : va_arg(ap, char *);
            int n = 0;
            while (*s && !isspace((unsigned char)*s) && (width == 0 || n < width)) {
                if (dst) dst[n] = *s;
                n++; s++;
            }
            if (dst) { dst[n] = 0; count++; }
            break;
        }
        case 'c': {
            char *dst = suppress ? NULL : va_arg(ap, char *);
            if (*s) { if (dst) { *dst = *s; count++; } s++; }
            break;
        }
        case '%':
            if (*s == '%') s++; else return count;
            break;
        default:
            return count;
        }
    }
    return count;
}
int sscanf(const char *str, const char *fmt, ...)
{
    va_list ap; va_start(ap, fmt);
    int n = vsscanf_impl(str, fmt, ap);
    va_end(ap);
    return n;
}
int fscanf(FILE *f, const char *fmt, ...)
{
    char line[512];
    if (!fgets(line, sizeof(line), f)) return -1;
    va_list ap; va_start(ap, fmt);
    int n = vsscanf_impl(line, fmt, ap);
    va_end(ap);
    return n;
}

